//! Minimal, dependency-free replacement for the `terminal_size` crate API
//! that is used by `clap_builder` (and by hexyl itself).

/// Terminal width in columns.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Width(pub u16);

/// Terminal height in rows.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Height(pub u16);

#[cfg(unix)]
mod imp {
    use super::{Height, Width};

    #[repr(C)]
    #[derive(Default)]
    struct WinSize {
        ws_row: u16,
        ws_col: u16,
        ws_xpixel: u16,
        ws_ypixel: u16,
    }

    extern "C" {
        fn isatty(fd: i32) -> i32;
        fn ioctl(fd: i32, request: std::os::raw::c_ulong, ...) -> i32;
    }

    #[cfg(any(target_os = "linux", target_os = "android"))]
    const TIOCGWINSZ: std::os::raw::c_ulong = 0x5413;
    #[cfg(not(any(target_os = "linux", target_os = "android")))]
    const TIOCGWINSZ: std::os::raw::c_ulong = 0x4008_7468;

    pub fn size_of_fd(fd: i32) -> Option<(Width, Height)> {
        unsafe {
            if isatty(fd) != 1 {
                return None;
            }
            let mut ws = WinSize::default();
            if ioctl(fd, TIOCGWINSZ, &mut ws as *mut WinSize) != 0 {
                return None;
            }
            if ws.ws_row > 0 && ws.ws_col > 0 {
                Some((Width(ws.ws_col), Height(ws.ws_row)))
            } else {
                None
            }
        }
    }
}

#[cfg(not(unix))]
mod imp {
    use super::{Height, Width};
    pub fn size_of_fd(_fd: i32) -> Option<(Width, Height)> {
        None
    }
}

/// Size of the terminal attached to the given raw file descriptor.
pub fn terminal_size_of_fd(fd: i32) -> Option<(Width, Height)> {
    imp::size_of_fd(fd)
}

/// Returns the size of the terminal, checking stdout, stderr and stdin
/// (in this order). The first stream that is a terminal wins.
pub fn terminal_size() -> Option<(Width, Height)> {
    imp::size_of_fd(1)
        .or_else(|| imp::size_of_fd(2))
        .or_else(|| imp::size_of_fd(0))
}
EOF
