{"command":"cat > /workspace/src/units.rs <<'EOF'
//! Parsing of byte counts / offsets such as `64`, `0xff`, `4KiB`, `-2block`.

use std::fmt;
use std::num::ParseIntError;

/// A parsed byte offset. `negative` reflects the sign character that was
/// given on the command line (so `-0` counts as negative).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ByteOffset {
    pub negative: bool,
    pub value: i64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum OffsetError {
    Empty,
    EmptyAfterSign,
    SignAfterHexPrefix(char),
    InvalidNumAndUnit(String),
    ParseNum(ParseIntError),
    InvalidUnit(String),
    UnitOverflow,
}

impl fmt::Display for OffsetError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            OffsetError::Empty => f.write_str("no character data found, did you forget to write it?"),
            OffsetError::EmptyAfterSign => {
                f.write_str("no digits found after sign, did you forget to write them?")
            }
            OffsetError::SignAfterHexPrefix(c) => write!(
                f,
                "found {c:?} sign after hex prefix (\"0x\"); signs should go before it"
            ),
            OffsetError::InvalidNumAndUnit(s) => {
                write!(f, "{s:?} is not of the expected form <pos-integer>[<unit>]")
            }
            OffsetError::ParseNum(_) => f.write_str("failed to parse integer part"),
            OffsetError::InvalidUnit(u) => write!(f, "invalid unit {u:?}"),
            OffsetError::UnitOverflow => f.write_str(
                "count multiplied by the unit overflowed a signed 64-bit integer; are you sure it should be that big?",
            ),
        }
    }
}

impl OffsetError {
    /// The chain of underlying causes (outermost first, excluding `self`).
    pub fn causes(&self) -> Vec<String> {
        match self {
            OffsetError::ParseNum(e) => vec![e.to_string()],
            _ => Vec::new(),
        }
    }

    /// Message and causes, outermost first.
    pub fn chain(&self) -> Vec<String> {
        let mut v = vec![self.to_string()];
        v.extend(self.causes());
        v
    }
}

/// Result of looking at a possible `0x` prefix.
pub enum HexParse {
    NotHex,
    Hex(Result<i64, OffsetError>),
}

/// Interpret `s` as a hexadecimal number if it starts with `0x`.
pub fn try_parse_hex(s: &str) -> HexParse {
    match s.strip_prefix("0x") {
        None => HexParse::NotHex,
        Some(digits) => {
            if let Some(c) = digits.chars().next() {
                if c == '+' || c == '-' {
                    return HexParse::Hex(Err(OffsetError::SignAfterHexPrefix(c)));
                }
            }
            HexParse::Hex(i64::from_str_radix(digits, 16).map_err(OffsetError::ParseNum))
        }
    }
}

/// Multiplier of a unit suffix (case insensitive). `block` units use `block_size`.
fn unit_multiplier(unit: &str, block_size: i64) -> Option<i64> {
    let lower = unit.to_ascii_lowercase();
    let m = match lower.as_str() {
        "kb" => 1000,
        "mb" => 1000 * 1000,
        "gb" => 1000 * 1000 * 1000,
        "tb" => 1000 * 1000 * 1000 * 1000,
        "kib" => 1 << 10,
        "mib" => 1 << 20,
        "gib" => 1 << 30,
        "tib" => 1 << 40,
        "block" | "blocks" => block_size,
        _ => return None,
    };
    Some(m)
}

fn is_block_unit(unit: &str) -> bool {
    let lower = unit.to_ascii_lowercase();
    lower == "block" || lower == "blocks"
}

/// Splits `s` into the leading decimal digits and the remaining unit.
fn split_digits(s: &str) -> (&str, &str) {
    let end = s
        .char_indices()
        .find(|(_, c)| !c.is_ascii_digit())
        .map(|(i, _)| i)
        .unwrap_or(s.len());
    s.split_at(end)
}

fn parse_count_with_unit(s: &str, block_size: i64) -> Result<i64, OffsetError> {
    let (digits, unit) = split_digits(s);
    if digits.is_empty() {
        return Err(OffsetError::InvalidNumAndUnit(s.to_owned()));
    }
    let multiplier = if unit.is_empty() {
        1
    } else {
        unit_multiplier(unit, block_size).ok_or_else(|| OffsetError::InvalidUnit(unit.to_owned()))?
    };
    let count: i64 = digits.parse().map_err(OffsetError::ParseNum)?;
    count
        .checked_mul(multiplier)
        .ok_or(OffsetError::UnitOverflow)
}

/// Parses a (possibly signed) byte offset.
pub fn parse_byte_offset(s: &str, block_size: i64) -> Result<ByteOffset, OffsetError> {
    if s.is_empty() {
        return Err(OffsetError::Empty);
    }
    let (negative, rest) = if let Some(r) = s.strip_prefix('-') {
        (true, r)
    } else if let Some(r) = s.strip_prefix('+') {
        (false, r)
    } else {
        (false, s)
    };
    if rest.is_empty() {
        return Err(OffsetError::EmptyAfterSign);
    }
    let magnitude = match try_parse_hex(rest) {
        HexParse::Hex(r) => r?,
        HexParse::NotHex => parse_count_with_unit(rest, block_size)?,
    };
    let value = if negative { -magnitude } else { magnitude };
    Ok(ByteOffset { negative, value })
}

/// Outcome of parsing the `--block-size` argument.
pub enum BlockSize {
    Size(i64),
    /// A hexadecimal block size was given; the original tool silently stops here.
    HexShortcut,
}

#[derive(Debug)]
pub enum BlockSizeError {
    Parse(OffsetError),
    BlockUnit,
    NotPositive,
}

impl BlockSizeError {
    pub fn chain(&self) -> Vec<String> {
        match self {
            BlockSizeError::Parse(e) => e.chain(),
            BlockSizeError::BlockUnit => {
                vec!["can not use 'block(s)' as a unit to specify block size".to_owned()]
            }
            BlockSizeError::NotPositive => vec!["block size argument must be positive".to_owned()],
        }
    }
}

pub fn parse_block_size(s: &str) -> Result<BlockSize, BlockSizeError> {
    if s.is_empty() {
        return Err(BlockSizeError::Parse(OffsetError::Empty));
    }
    if let HexParse::Hex(r) = try_parse_hex(s) {
        let v = r.map_err(BlockSizeError::Parse)?;
        return if v > 0 {
            Ok(BlockSize::HexShortcut)
        } else {
            Err(BlockSizeError::NotPositive)
        };
    }
    let (digits, unit) = split_digits(s);
    if digits.is_empty() {
        return Err(BlockSizeError::Parse(OffsetError::InvalidNumAndUnit(s.to_owned())));
    }
    if is_block_unit(unit) {
        return Err(BlockSizeError::BlockUnit);
    }
    let v = parse_count_with_unit(s, 1).map_err(BlockSizeError::Parse)?;
    if v <= 0 {
        return Err(BlockSizeError::NotPositive);
    }
    Ok(BlockSize::Size(v))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn simple() {
        assert_eq!(parse_byte_offset("64", 512).unwrap().value, 64);
        assert_eq!(parse_byte_offset("0x40", 512).unwrap().value, 64);
        assert_eq!(parse_byte_offset("4KiB", 512).unwrap().value, 4096);
        assert_eq!(parse_byte_offset("2block", 512).unwrap().value, 1024);
        assert!(parse_byte_offset("-0", 512).unwrap().negative);
    }
}
EOF
echo ok"}

