//! Color handling: ANSI escape sequences, user configurable colors (via
//! `HEXYL_COLOR_*` environment variables) and terminal color detection.

use std::env;
use std::io::IsTerminal;

pub const RESET: &[u8] = b"\x1b[39m";

/// Byte categories that can be configured by the user.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Category {
    Null = 0,
    AsciiPrintable = 1,
    AsciiWhitespace = 2,
    AsciiOther = 3,
    NonAscii = 4,
    Offset = 5,
}

impl Category {
    pub fn of_byte(b: u8) -> Category {
        if b == 0 {
            Category::Null
        } else if b.is_ascii_graphic() {
            Category::AsciiPrintable
        } else if b.is_ascii_whitespace() {
            Category::AsciiWhitespace
        } else if b.is_ascii() {
            Category::AsciiOther
        } else {
            Category::NonAscii
        }
    }

    fn env_var(self) -> &'static str {
        match self {
            Category::Null => "HEXYL_COLOR_NULL",
            Category::AsciiPrintable => "HEXYL_COLOR_ASCII_PRINTABLE",
            Category::AsciiWhitespace => "HEXYL_COLOR_ASCII_WHITESPACE",
            Category::AsciiOther => "HEXYL_COLOR_ASCII_OTHER",
            Category::NonAscii => "HEXYL_COLOR_NONASCII",
            Category::Offset => "HEXYL_COLOR_OFFSET",
        }
    }

    fn default_code(self) -> u8 {
        match self {
            Category::Null => 90,
            Category::AsciiPrintable => 36,
            Category::AsciiWhitespace => 32,
            Category::AsciiOther => 32,
            Category::NonAscii => 33,
            Category::Offset => 90,
        }
    }
}

fn ansi(code: u8) -> Vec<u8> {
    format!("\x1b[{code}m").into_bytes()
}

/// Error raised when the configured color specification would crash the
/// original color parser (slicing in the middle of a UTF-8 sequence).
pub struct ColorPanic {
    pub message: String,
}

fn char_boundary_panic(s: &str, begin: usize, end: usize) -> ColorPanic {
    let index = if !s.is_char_boundary(begin) { begin } else { end };
    let mut char_start = index;
    while !s.is_char_boundary(char_start) {
        char_start -= 1;
    }
    let ch = s[char_start..].chars().next().unwrap_or('\0');
    let char_end = char_start + ch.len_utf8();
    ColorPanic {
        message: format!(
            "byte index {index} is not a char boundary; it is inside {ch:?} (bytes {char_start}..{char_end}) of `{s}`"
        ),
    }
}

/// Parses a color specification the same way as the original tool did.
/// `Ok(None)` means "invalid, use the default".
fn parse_color(s: &str) -> Result<Option<Vec<u8>>, ColorPanic> {
    let first = match s.chars().next() {
        Some(c) => c,
        None => return Ok(None),
    };
    if first == '#' {
        if s.len() != 7 {
            return Ok(None);
        }
        let mut rgb = [0u8; 3];
        for (i, slot) in rgb.iter_mut().enumerate() {
            let begin = 1 + 2 * i;
            let end = begin + 2;
            let part = match s.get(begin..end) {
                Some(p) => p,
                None => return Err(char_boundary_panic(s, begin, end)),
            };
            match u8::from_str_radix(part, 16) {
                Ok(v) => *slot = v,
                Err(_) => return Ok(None),
            }
        }
        return Ok(Some(
            format!("\x1b[38;2;{};{};{}m", rgb[0], rgb[1], rgb[2]).into_bytes(),
        ));
    }
    let code = match s {
        "black" => 30,
        "red" => 31,
        "green" => 32,
        "yellow" => 33,
        "blue" => 34,
        "magenta" | "purple" => 35,
        "cyan" => 36,
        "white" => 37,
        "bright black" => 90,
        "bright red" => 91,
        "bright green" => 92,
        "bright yellow" => 93,
        "bright blue" => 94,
        "bright magenta" => 95,
        "bright cyan" => 96,
        "bright white" => 97,
        _ => return Ok(None),
    };
    Ok(Some(ansi(code)))
}

/// Lazily resolved colors of all categories.
pub struct Palette {
    resolved: [Option<Vec<u8>>; 6],
}

impl Palette {
    pub fn new() -> Palette {
        Palette {
            resolved: Default::default(),
        }
    }

    /// Escape sequence for the given category, resolving it on first use.
    pub fn get(&mut self, cat: Category) -> Result<&[u8], ColorPanic> {
        let idx = cat as usize;
        if self.resolved[idx].is_none() {
            let parsed = match env::var(cat.env_var()) {
                Ok(s) => parse_color(&s)?,
                Err(_) => None,
            };
            self.resolved[idx] = Some(parsed.unwrap_or_else(|| ansi(cat.default_code())));
        }
        Ok(self.resolved[idx].as_deref().unwrap())
    }
}

/// Location reported by the original tool when the color parser crashed.
pub const COLOR_PANIC_LOCATION: &str = "/usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/owo-colors-4.1.0/src/dyn_colors.rs:83:42";

/// Prints a message that mimics the default Rust panic output.
pub fn report_panic(location: &str, message: &str) {
    let tid = current_thread_id();
    eprint!(
        "\nthread 'main' ({tid}) panicked at {location}:\n{message}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n"
    );
}

fn current_thread_id() -> u64 {
    #[cfg(target_os = "linux")]
    {
        extern "C" {
            fn gettid() -> i32;
        }
        unsafe { gettid() as u64 }
    }
    #[cfg(not(target_os = "linux"))]
    {
        std::process::id() as u64
    }
}

fn env_str(name: &str) -> Option<String> {
    env::var(name).ok()
}

fn force_color_level() -> usize {
    if let Some(force) = env_str("FORCE_COLOR") {
        match force.as_str() {
            "true" | "" => 1,
            "false" => 0,
            f => std::cmp::min(f.parse().unwrap_or(1), 3),
        }
    } else if let Some(force) = env_str("CLICOLOR_FORCE") {
        usize::from(force != "0")
    } else {
        0
    }
}

fn is_ci() -> bool {
    if let Some(ci) = env::var_os("CI") {
        if ci == "true" || ci == "1" || ci == "woodpecker" {
            return true;
        }
    }
    if let Some(node) = env::var_os("NODE") {
        if node.to_string_lossy().ends_with("//heroku/node/bin/node") {
            return true;
        }
    }
    const PRESENCE: &[&str] = &[
        "CI_NAME",
        "GITLAB_CI",
        "TRAVIS",
        "CIRCLECI",
        "APPVEYOR",
        "DRONE",
        "SEMAPHORE",
        "NETLIFY",
        "BUDDY_WORKSPACE_ID",
        "BUILDKITE",
        "CIRRUS_CI",
        "HUDSON_URL",
        "JENKINS_URL",
        "NOW_BUILDER",
        "NOW_GITHUB_DEPLOYMENT",
        "DSARI",
        "NEVERCODE",
        "BUILDER_OUTPUT",
        "SHIPPABLE",
        "STRIDER",
        "TDDIUM",
        "MAGNUM",
        "bamboo.buildKey",
        "SYSTEM_TEAMFOUNDATIONCOLLECTIONURI",
        "BITRISE_IO",
        "TASKCLUSTER_ROOT_URL",
        "SAIL_CI",
        "RENDER",
        "GERRIT_PROJECT",
        "GITHUB_ACTION",
        "WERCKER",
        "CODEBUILD_SRC_DIR",
        "GO_PIPELINE_NAME",
    ];
    PRESENCE.iter().any(|v| env::var_os(v).is_some())
}

/// Whether standard output supports colors (used for `--color=auto`).
pub fn stdout_supports_color() -> bool {
    if force_color_level() > 0 {
        return true;
    }
    let no_color = matches!(env_str("NO_COLOR").as_deref(), Some(v) if v != "0");
    let term = env_str("TERM");
    let ignore_tty = matches!(env_str("IGNORE_IS_TERMINAL").as_deref(), Some(v) if v != "0");
    if no_color
        || term.as_deref() == Some("dumb")
        || !(std::io::stdout().is_terminal() || ignore_tty)
    {
        return false;
    }
    let term_program = env_str("TERM_PROGRAM");
    env::var_os("COLORTERM").is_some()
        || term.is_some()
        || term_program.as_deref() == Some("iTerm.app")
        || term_program.as_deref() == Some("Apple_Terminal")
        || matches!(env_str("CLICOLOR").as_deref(), Some(v) if v != "0")
        || is_ci()
}
EOF
