            writer,
            palette: Palette::new(),
            gradient,
            line_len,
            line_buf: vec![0u8; line_len],
            out: Vec::with_capacity(256),
            idx: 0,
            squeezer,
            squeeze_byte: 0,
            s,
        }
    }

    fn flush_line(&mut self) -> io::Result<()> {
        self.writer.write_all(&self.out)?;
        self.out.clear();
        Ok(())
    }

    /// Writes out whatever has been assembled so far (used before crashing).
    pub fn emergency_flush(&mut self) {
        let _ = self.writer.write_all(&self.out);
        self.out.clear();
        let _ = self.writer.flush();
    }

    /// Width of a hex panel content (without the surrounding spaces).
    fn hex_content_width(&self, digits: usize) -> usize {
        let groups = 8 / self.s.group_size as usize;
        8 * digits + groups - 1
    }

    fn write_border_line(&mut self, chars: &BorderChars, digits: usize) -> io::Result<()> {
        let hex_w = self.hex_content_width(digits) + 2;
        let mut line = String::new();
        line.push_str(chars.left_corner);
        if self.s.show_position_panel {
            line.push_str(&chars.horizontal.repeat(8));
            line.push_str(chars.column_separator);
        }
        let h = chars.horizontal.repeat(hex_w);
        for i in 0..self.s.panels {
            if i > 0 {
                line.push_str(chars.column_separator);
            }
            line.push_str(&h);
        }
        if self.s.show_char_panel {
            let h8 = chars.horizontal.repeat(8);
            for _ in 0..self.s.panels {
                line.push_str(chars.column_separator);
                line.push_str(&h8);
            }
        }
        line.push_str(chars.right_corner);
        line.push('\n');
        self.writer.write_all(line.as_bytes())
    }

    fn print_header(&mut self, digits: usize) -> io::Result<()> {
        if let Some(chars) = self.s.border_style.header_chars() {
            self.write_border_line(&chars, digits)?;
        }
        Ok(())
    }

    fn print_footer(&mut self, digits: usize) -> io::Result<()> {
        if let Some(chars) = self.s.border_style.footer_chars() {
            self.write_border_line(&chars, digits)?;
        }
        Ok(())
    }

    fn color_of(&mut self, b: u8) -> Result<&[u8], ColorPanic> {
        if let Some(g) = &self.gradient {
            return Ok(&g[b as usize]);
        }
        self.palette.get(Category::of_byte(b))
    }

    fn push_position(&mut self, pos: u64) {
        let bytes = pos.to_be_bytes();
        let first = bytes.iter().position(|&b| b != 0).unwrap_or(8);
        let start = std::cmp::min(first, 4);
        for &b in &bytes[start..] {
            self.out.push(DIGITS[(b >> 4) as usize]);
            self.out.push(DIGITS[(b & 0xf) as usize]);
        }
    }

    fn push_byte_digits(&mut self, b: u8) {
        match self.s.base {
            Base::Hexadecimal => {
                self.out.push(DIGITS[(b >> 4) as usize]);
                self.out.push(DIGITS[(b & 0xf) as usize]);
            }
            Base::Decimal => {
                self.out.push(b'0' + b / 100);
                self.out.push(b'0' + (b / 10) % 10);
                self.out.push(b'0' + b % 10);
            }
            Base::Octal => {
                self.out.push(b'0' + (b >> 6));
                self.out.push(b'0' + ((b >> 3) & 7));
                self.out.push(b'0' + (b & 7));
            }
            Base::Binary => {
                for i in (0..8).rev() {
                    self.out.push(b'0' + ((b >> i) & 1));
                }
            }
        }
    }

    fn push_char(&mut self, b: u8) {
        let mut tmp = [0u8; 4];
        let c: char = match self.s.char_table {
            CharTable::Default => {
                if b == 0 {
                    '⋄'
                } else if b.is_ascii_graphic() || b == b' ' {
                    b as char
                } else if b.is_ascii_whitespace() {
                    '_'
                } else if b.is_ascii() {
                    '•'
                } else {
                    '×'
                }
            }
            CharTable::Ascii => {
                if b.is_ascii_graphic() || b == b' ' {
                    b as char
                } else {
                    '.'
                }
            }
            CharTable::CP1047 => CP1047[b as usize] as char,
            CharTable::CP437 => CP437[b as usize],
            CharTable::Braille => match b {
                0x00 => '⋄',
                b'\t' => '→',
                b'\n' => '↵',
                b'\r' => '←',
                0x20..=0x7e => b as char,
                _ => {
                    let v = b as u32;
                    let mapped = (v & 0b1110_0001)
                        | ((v & 0b0000_0010) << 2)
                        | ((v & 0b0000_0100) >> 1)
                        | ((v & 0b0000_1000) << 1)
                        | ((v & 0b0001_0000) >> 2);
                    char::from_u32(0x2800 + mapped).unwrap_or('?')
                }
            },
        };
        self.out.extend_from_slice(c.encode_utf8(&mut tmp).as_bytes());
    }

    fn push_offset_color(&mut self) -> Result<(), ColorPanic> {
        if self.s.show_color {
            let c = self.palette.get(Category::Offset)?.to_vec();
            self.out.extend_from_slice(&c);
        }
        Ok(())
    }

    /// Appends `c` to the output if it differs from the currently active color.
    fn switch_color(&mut self, b: u8, active: &mut Option<Vec<u8>>) -> Result<(), ColorPanic> {
        if !self.s.show_color {
            return Ok(());
        }
        let c = self.color_of(b)?;
        if active.as_deref() != Some(c) {
            let c = c.to_vec();
            self.out.extend_from_slice(&c);
            *active = Some(c);
        }
        Ok(())
    }

    fn push_reset(&mut self) {
        if self.s.show_color {
            self.out.extend_from_slice(RESET);
        }
    }

    fn build_line(&mut self, len: usize, kind: LineKind) -> Result<(), ColorPanic> {
        let outer = self.s.border_style.outer();
        let inner = self.s.border_style.inner();
        let data_len = if kind == LineKind::Data { len } else { 0 };

        // position panel
        self.out.extend_from_slice(outer);
        self.push_offset_color()?;
        if self.s.show_position_panel {
            if kind == LineKind::Squeezed {
                self.out.push(b'*');
                self.push_reset();
                self.out.extend_from_slice(b"       ");
            } else {
                let pos = self.s.display_offset.wrapping_add(self.idx);
                self.push_position(pos);
                self.push_reset();
            }
            self.out.extend_from_slice(outer);
        }

        // hex panels
        let digits = self.s.base.digits();
        let content_w = self.hex_content_width(digits);
        let group = self.s.group_size as usize;
        let panels = self.s.panels as usize;
        for p in 0..panels {
            if p == 0 && kind != LineKind::Data && !self.s.show_position_panel {
                self.push_offset_color()?;
                self.out.push(b'*');
                self.push_reset();
            } else {
                self.out.push(b' ');
            }
            let start_len = self.out.len();
            let mut written = 0usize;
            let panel_start = p * 8;
            if panel_start < data_len {
                let panel_end = std::cmp::min(panel_start + 8, data_len);
                let mut active: Option<Vec<u8>> = None;
                let mut g_start = panel_start;
                while g_start < panel_end {
                    let g_end = std::cmp::min(g_start + group, panel_end);
                    if g_start > panel_start {
                        self.out.push(b' ');
                        written += 1;
                    }
                    for k in 0..(g_end - g_start) {
                        let i = match self.s.endianness {
                            Endianness::Big => g_start + k,
                            Endianness::Little => g_end - 1 - k,
                        };
                        let b = self.line_buf[i];
                        self.switch_color(b, &mut active)?;
                        self.push_byte_digits(b);
                        written += digits;
                    }
                    g_start = g_end;
                }
            }
            let _ = start_len;
            for _ in written..content_w {
                self.out.push(b' ');
            }
            self.push_reset();
            self.out.push(b' ');
            self.out
                .extend_from_slice(if p + 1 == panels { outer } else { inner });
        }

        // character panels
        if self.s.show_char_panel {
            for p in 0..panels {
                let panel_start = p * 8;
                let mut written = 0;
                if panel_start < data_len {
                    let panel_end = std::cmp::min(panel_start + 8, data_len);
                    let mut active: Option<Vec<u8>> = None;
                    for i in panel_start..panel_end {
                        let b = self.line_buf[i];
                        self.switch_color(b, &mut active)?;
                        self.push_char(b);
                        written += 1;
                    }
                }
                for _ in written..8 {
                    self.out.push(b' ');
                }
                self.push_reset();
                self.out
                    .extend_from_slice(if p + 1 == panels { outer } else { inner });
            }
        }
        self.out.push(b'\n');
        Ok(())
    }

    fn print_line(&mut self, len: usize, kind: LineKind) -> Result<(), PrintError> {
        self.build_line(len, kind).map_err(PrintError::Panic)?;
        self.flush_line()?;
        Ok(())
    }

    fn line_is_uniform(&self, byte: u8) -> bool {
        self.line_buf.iter().all(|&b| b == byte)
    }

    /// Fills the line buffer; returns the number of bytes read (less than
    /// a full line only at the end of the input).
    fn fill_line<R: Read>(&mut self, reader: &mut R) -> Option<usize> {
        let mut filled = 0;
        while filled < self.line_len {
            match reader.read(&mut self.line_buf[filled..]) {
                Ok(0) => return Some(filled),
                Ok(n) => filled += n,
                Err(_) => {
                    if filled == 0 {
                        // read errors are ignored: the previous buffer content is reused
                        return None;
                    }
                }
            }
        }
        None
    }

    fn print_no_content(&mut self) -> io::Result<()> {
        self.print_header(2)?;
        let hex_w = self.hex_content_width(2) + 2;
        let mut line = String::from("│");
        if self.s.show_position_panel {
            line.push_str("        │");
        }
        line.push_str(&format!("{:<w$}", " No content", w = hex_w));
        line.push('│');
        line.push_str(&" ".repeat(hex_w));
        line.push('│');
        if self.s.show_char_panel {
            line.push_str("        │        │");
        }
        line.push('\n');
        self.writer.write_all(line.as_bytes())?;
        self.print_footer(2)
    }

    pub fn print_all<R: Read>(&mut self, mut reader: R) -> Result<(), PrintError> {
        let digits = self.s.base.digits();
        let mut is_empty = true;
        let line_len = self.line_len;

        let leftover = loop {
            let n = self.fill_line(&mut reader);
            match n {
                Some(0) => {
                    if self.squeezer == Squeezer::Delete {
                        break Some(0);
                    }
                    break None;
                }
                Some(n) => {
                    if is_empty {
                        self.print_header(digits)?;
                        is_empty = false;
                    }
                    break Some(n);
                }
                None => {}
            }
            if is_empty {
                self.print_header(digits)?;
            }

            if matches!(self.squeezer, Squeezer::Print | Squeezer::Delete) {
                if self.line_is_uniform(self.squeeze_byte) {
                    if self.squeezer == Squeezer::Delete {
                        self.idx = self.idx.wrapping_add(line_len as u64);
                        continue;
                    }
                } else {
                    self.squeezer = Squeezer::Ignore;
                }
            }

            let kind = if self.squeezer == Squeezer::Print {
                LineKind::Squeezed
            } else {
                LineKind::Data
            };
            self.print_line(line_len, kind)?;

            if is_empty {
                self.writer.flush()?;
                is_empty = false;
            }

            self.idx = self.idx.wrapping_add(line_len as u64);

            if self.squeezer == Squeezer::Print {
                self.squeezer = Squeezer::Delete;
            }

            if !matches!(self.squeezer, Squeezer::Disabled | Squeezer::Delete) && line_len > 0 {
                let first = self.line_buf[0];
                if self.line_is_uniform(first) {
                    self.squeezer = Squeezer::Print;
                    self.squeeze_byte = first;
                }
            }
        };

        match leftover {
            Some(0) => {
                // end of squeezed content: only show the final position
                self.print_line(0, LineKind::End)?;
            }
            Some(n) => {
                self.print_line(n, LineKind::Data)?;
            }
            None => {}
        }

        if is_empty {
            self.print_no_content()?;
        } else {
            self.print_footer(digits)?;
        }
        self.writer.flush()?;
        Ok(())
    }
}
