//! Input sources (file or standard input) including skipping.

use std::fs::File;
use std::io::{self, Read, Seek, SeekFrom};

pub enum Input {
    File(File),
    Stdin(io::Stdin),
}

impl Read for Input {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        match self {
            Input::File(f) => f.read(buf),
            Input::Stdin(s) => s.read(buf),
        }
    }
}

fn skip_by_reading<R: Read>(reader: &mut R, n: u64) -> io::Result<u64> {
    io::copy(&mut reader.take(n), &mut io::sink())
}

const ESPIPE: i32 = 29;

impl Input {
    /// Moves the read position. A non-negative `offset` skips forward relative
    /// to the current position; a negative one seeks relative to the end.
    pub fn jump(&mut self, negative: bool, offset: i64) -> io::Result<u64> {
        match self {
            Input::Stdin(stdin) => {
                if negative {
                    Err(io::Error::other("stdin being seeked"))
                } else {
                    skip_by_reading(stdin, offset as u64)
                }
            }
            Input::File(file) => {
                let pos = if negative {
                    SeekFrom::End(offset)
                } else {
                    SeekFrom::Current(offset)
                };
                match file.seek(pos) {
                    Ok(p) => Ok(p),
                    Err(e) if e.raw_os_error() == Some(ESPIPE) => {
                        if negative {
                            Err(io::Error::other("file non-seekable"))
                        } else {
                            skip_by_reading(file, offset as u64)
                        }
                    }
                    Err(e) => Err(e),
                }
            }
        }
    }
}
