//! hexyl - a command-line hex viewer.

mod cli;
mod colors;
mod input;
mod printer;
mod tables;
mod units;

use std::fs::File;
use std::io::{self, BufWriter, IsTerminal, Read, Write};
use std::num::NonZeroU64;
use std::path::PathBuf;

use clap_builder::parser::ValueSource;
use clap_builder::ArgMatches;

use crate::colors::{Category, Palette};
use crate::input::Input;
use crate::printer::{
    Base, BorderStyle, CharTable, ColorScheme, Endianness, PrintError, Printer, Settings,
};
use crate::units::{parse_block_size, parse_byte_offset, BlockSize};

/// An error reported to the user as `Error: ...` (in the style of `anyhow`).
struct AppError {
    /// Outermost message first, followed by its causes.
    chain: Vec<String>,
    io_kind: Option<io::ErrorKind>,
}

impl AppError {
    fn msg(m: impl Into<String>) -> AppError {
        AppError {
            chain: vec![m.into()],
            io_kind: None,
        }
    }

    fn with_chain(chain: Vec<String>) -> AppError {
        AppError {
            chain,
            io_kind: None,
        }
    }

    fn report(&self) -> String {
        let mut s = format!("Error: {}", self.chain[0]);
        let causes = &self.chain[1..];
        if !causes.is_empty() {
            s.push_str("\n\nCaused by:");
            if causes.len() == 1 {
                s.push_str("\n    ");
                s.push_str(&causes[0].replace('\n', "\n    "));
            } else {
                for (i, c) in causes.iter().enumerate() {
                    s.push_str(&format!("\n{i:>5}: "));
                    s.push_str(&c.replace('\n', "\n       "));
                }
            }
        }
        s
    }
}

impl From<io::Error> for AppError {
    fn from(e: io::Error) -> AppError {
        AppError {
            chain: vec![e.to_string()],
            io_kind: Some(e.kind()),
        }
    }
}

/// Outcome of running the program successfully.
enum Exit {
    Success,
}

enum Failure {
    Error(AppError),
    /// Emulates a crash of the original program.
    Panic { location: String, message: String },
}

impl From<AppError> for Failure {
    fn from(e: AppError) -> Failure {
        Failure::Error(e)
    }
}

impl From<io::Error> for Failure {
    fn from(e: io::Error) -> Failure {
        Failure::Error(e.into())
    }
}

fn byte_count_error(arg: &str, value: &str, chain: Vec<String>) -> AppError {
    let mut c = vec![format!("failed to parse `--{arg}` arg {value:?} as byte count")];
    c.extend(chain);
    AppError::with_chain(c)
}

const NEGATIVE_NOT_ALLOWED: &str =
    "negative offset specified, but only positive offsets (counts) are accepted in this context";

fn parse_count_arg(m: &ArgMatches, id: &str, block_size: i64) -> Result<Option<u64>, AppError> {
    let Some(value) = m.get_one::<String>(id) else {
        return Ok(None);
    };
    let arg = match id {
        "length" => "length",
        "display_offset" => "display-offset",
        other => other,
    };
    let off = parse_byte_offset(value, block_size)
        .map_err(|e| byte_count_error(arg, value, e.chain()))?;
    if off.negative {
        return Err(byte_count_error(
            arg,
            value,
            vec![NEGATIVE_NOT_ALLOWED.to_owned()],
        ));
    }
    Ok(Some(off.value as u64))
}

fn parse_base(s: &str) -> Result<Base, AppError> {
    if let Ok(n) = s.parse::<u8>() {
        return match n {
            2 => Ok(Base::Binary),
            8 => Ok(Base::Octal),
            10 => Ok(Base::Decimal),
            16 => Ok(Base::Hexadecimal),
            _ => Err(AppError::msg(
                "The number provided is not a valid base. Valid bases are 2, 8, 10, and 16.",
            )),
        };
    }
    match s {
        "b" | "bin" | "binary" => Ok(Base::Binary),
        "o" | "oct" | "octal" => Ok(Base::Octal),
        "d" | "dec" | "decimal" => Ok(Base::Decimal),
        "x" | "hex" | "hexadecimal" => Ok(Base::Hexadecimal),
        _ => Err(AppError::msg(
            "The base provided is not valid. Valid bases are \"b\", \"o\", \"d\", and \"x\".",
        )),
    }
}

fn is_explicit(m: &ArgMatches, id: &str) -> bool {
    matches!(m.value_source(id), Some(ValueSource::CommandLine))
}

fn print_color_table() {
    let mut palette = Palette::new();
    let order = [
        Category::Null,
        Category::AsciiPrintable,
        Category::AsciiWhitespace,
        Category::AsciiOther,
        Category::NonAscii,
    ];
    let mut codes = Vec::new();
    for cat in order {
        match palette.get(cat) {
            Ok(c) => codes.push(String::from_utf8_lossy(c).into_owned()),
            Err(p) => {
                colors::report_panic(colors::COLOR_PANIC_LOCATION, &p.message);
                std::process::exit(101);
            }
        }
    }
    let reset = "\x1b[39m";
    let text = format!(
        "hexyl color reference:\n\n\
         {}\u{22c4} NULL bytes (0x00)\n{reset}\
         {}a ASCII printable characters (0x20 - 0x7E)\n{reset}\
         {}_ ASCII whitespace (0x09 - 0x0D, 0x20)\n{reset}\
         {}\u{2022} ASCII control characters (except NULL and whitespace)\n{reset}\
         {}\u{d7} Non-ASCII bytes (0x80 - 0xFF)\n{reset}",
        codes[0], codes[1], codes[2], codes[3], codes[4]
    );
    let stdout = io::stdout();
    let mut w = BufWriter::new(stdout.lock());
    let _ = w.write_all(text.as_bytes());
    // errors while flushing are ignored (like dropping a BufWriter)
}

fn print_completion(shell: &str) -> Result<Exit, Failure> {
    let script: &str = match shell {
        "bash" => include_str!("completions/hexyl.bash"),
        "elvish" => include_str!("completions/hexyl.elvish"),
        "fish" => include_str!("completions/hexyl.fish"),
        "powershell" => include_str!("completions/hexyl.powershell"),
        _ => include_str!("completions/hexyl.zsh"),
    };
    let stdout = io::stdout();
    let mut lock = stdout.lock();
    if let Err(e) = lock.write_all(script.as_bytes()).and_then(|_| lock.flush()) {
