            location: "/usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/clap_complete-4.5.55/src/aot/shells/shell.rs:86:14".to_owned(),
            message: format!("failed to write completion file: {e:?}"),
        });
    }
    Ok(Exit::Success)
}

/// Width of the terminal used for calculating the number of panels.
fn terminal_width() -> u64 {
    terminal_size::terminal_size()
        .map(|(w, _)| w.0 as u64)
        .unwrap_or(80)
