fn print_include<R: Read>(mut reader: R, name: Option<String>) -> Result<(), io::Error> {
    let stdout = io::stdout();
    let mut w = BufWriter::new(stdout.lock());
    if let Some(n) = &name {
        writeln!(w, "unsigned char {n}[] = {{")?;
    }
    let mut total: u64 = 0;
    let mut buf = vec![0u8; 64 * 1024];
    let mut col = 0usize;
    let mut line = Vec::with_capacity(128);
    loop {
        let n = match reader.read(&mut buf) {
            Ok(0) => break,
            Ok(n) => n,
            Err(e) if e.kind() == io::ErrorKind::Interrupted => continue,
            Err(e) => return Err(e),
        };
        for &b in &buf[..n] {
            if col == 12 {
                line.extend_from_slice(b",\n");
                w.write_all(&line)?;
                line.clear();
                col = 0;
            }
            if col == 0 {
