        Some("ascii") => CharTable::Ascii,
        Some("codepage-1047") => CharTable::CP1047,
        Some("codepage-437") => CharTable::CP437,
        Some("braille") => CharTable::Braille,
        _ => CharTable::Default,
    };
    let color_scheme = match m.get_one::<String>("color_scheme").map(String::as_str) {
        Some("gradient") => ColorScheme::Gradient,
        _ => ColorScheme::Default,
    };

