        show_color,
        show_char_panel,
        show_position_panel,
        border_style,
        squeeze: !m.get_flag("no_squeezing"),
        panels,
        group_size,
        base,
        endianness,
        char_table,
        color_scheme,
        display_offset: display_offset.wrapping_add(start_position),
    };

    let stdout = io::stdout();
    let writer = BufWriter::new(stdout.lock());
    let mut printer = Printer::new(writer, settings);
    match printer.print_all(reader) {
        Ok(()) => Ok(Exit::Success),
        Err(PrintError::Io(e)) => Err(e.into()),
        Err(PrintError::Panic(p)) => {
            colors::report_panic(colors::COLOR_PANIC_LOCATION, &p.message);
