            std::process::exit(101);
        }
    }
}

fn main() {
    let matches = cli::build_command().get_matches();
    let _ = io::stdout().is_terminal();
    let code = match run(&matches) {
        Ok(Exit::Success) => 0,
        Err(Failure::Error(e)) => {
            if e.io_kind == Some(io::ErrorKind::BrokenPipe) {
                0
            } else {
                eprintln!("{}", e.report());
                1
            }
        }
        Err(Failure::Panic { location, message }) => {
            colors::report_panic(&location, &message);
            101
        }
    };
    std::process::exit(code);
}
